// Package invui draws menus in a chest window kept open while the server
// rewrites its slots: every element of a screen is a slot whose item and
// name the inventoryui pack's sg_menu.json draws (generated by
// tools/invuigen from this layout), and a press on a slot drops one item,
// which the server cancels and answers.
package invui

import "strings"

// Marker in the window title makes the pack draw the menu window.
const Marker = "§s§g§m§u"

// The slots every screen shares: the screen's key, its title, its body
// text, a second text (a split screen's status) and the page arrows of a
// split screen.
const (
	SlotKey   = 0
	SlotTitle = 1
	SlotBody  = 2
	SlotInfo  = 3
	SlotPrev  = 4
	SlotNext  = 5
)

// Tabs are the tabs over the window: an icon and a button slot each.
const (
	Tabs     = 8
	TabIcon0 = 6
	TabBtn0  = TabIcon0 + Tabs
)

// Bars are the buttons of the control bar, left of the close button.
const (
	Bars     = 6
	BarIcon0 = TabBtn0 + Tabs
	BarBtn0  = BarIcon0 + Bars
)

// Rows are the elements with an icon and a label: an icon and a button slot
// each. The screen's layout draws them as list rows, cards or actions.
const (
	Rows     = 48
	RowIcon0 = BarBtn0 + Bars
	RowBtn0  = RowIcon0 + Rows
)

// Cells are the item slots of a screen's grid: one slot each, holding the
// item itself named with its tooltip.
const (
	Cells = 110
	Cell0 = RowBtn0 + Rows
)

// SlotLogo and SlotGame are the logo and the game's name the lobby draws over
// its screens (KeyLobby). SlotEsc is pressed by Esc: the screen's close runs
// with the window kept open, so the next screen does not reopen it.
const (
	SlotLogo = Cell0 + Cells
	SlotGame = SlotLogo + 1
	SlotEsc  = SlotGame + 1
)

// Size is the number of slots of the menu window: the most a window was seen
// to read (bedrock-research HOST-16 and the entity examples use 243).
const Size = SlotEsc + 1

// The slots of the home screen (KeyHome): the profile card, the square
// buttons at the top right with their badges, the tiles down the left, the
// feed lines, the chosen save's card, the play and manage buttons and the
// overlay panel. Row numbers count from RowIcon0 and RowBtn0, cells from
// Cell0.
const (
	HomeProfileRow = 0
	HomeCornerRow0 = 1
	HomeCorners    = 6
	HomeSideRow0   = HomeCornerRow0 + HomeCorners
	HomeSides      = 8
	HomeSaveRow    = HomeSideRow0 + HomeSides
	HomePlayRow    = HomeSaveRow + 1
	HomeManageRow  = HomePlayRow + 1
	HomeOverRow0   = HomeManageRow + 1
	HomeOvers      = 6

	HomeTitleCell  = 0
	HomeLineCell   = 1
	HomeFillCell   = 2
	HomeBadgeCell0 = 3
	HomeFeedCell0  = HomeBadgeCell0 + HomeCorners
	HomeFeeds      = 8
	HomeHeadCell   = HomeFeedCell0 + HomeFeeds
	HomeLineCell0  = HomeHeadCell + 1
	HomeLines      = 4
	HomeSubCell    = HomeLineCell0 + HomeLines
	HomeOverTitle  = HomeSubCell + 1
	HomeOverBody   = HomeOverTitle + 1
	HomeSideBadge0 = HomeOverBody + 1

	// HomeFillSteps is how many widths the profile's bar is drawn in.
	HomeFillSteps = 20
)

// The slots of the range screen (KeyRange): an axis a line, the offset's x,
// y and z then the reach's, each with its value in a cell and a minus and a
// plus button in the rows; the two headings in the cells after the axes and
// the 3D preview's box ("v1" to "v6", RangePreviews) in the next. The rows
// from RangeRow0 are list rows.
const (
	RangeAxes  = 6
	RangeHead0 = RangeAxes
	RangeHead1 = RangeAxes + 1
	RangeView  = RangeAxes + 2
	RangeRow0  = 2 * RangeAxes
)

// RangePreviews are the sizes of the boxes the range screen's 3D preview
// draws, each a cube from (-size/2, PreviewY, -size/2), left as a client
// only copy of the area being set.
var RangePreviews = [...]int{10, 16, 24, 32, 48, 64}

// PreviewY is the height of the bottom of the preview boxes.
const PreviewY = 256

// The layouts of the screens, by the key in SlotKey. KeyList after a key
// draws it on the list page (the body over the layout's content), and
// KeyRows the list rows under that content.
const (
	KeyList      = "L"
	KeyMenu      = "mn"
	KeyCards     = "cd"
	KeyGrid      = "gd"
	KeyBoard     = "bd"
	KeySplit     = "sp"
	KeyListSplit = "ls"
	KeyHome      = "hm"
	// KeyLoading draws the loading screen over the whole screen: the
	// picture in the first row's icon, the title in SlotTitle, the small
	// line under it in SlotInfo, the line ending in dots in SlotBody and the
	// tip in the first cell.
	KeyLoading = "ld"
	KeyRange   = "rg"
	// KeyPick draws big cards to pick one of: card i is row i (its icon, and
	// its title with the rarity's kind on the button) with its tag in cell 2i
	// and its text in cell 2i+1. Rows from PickCards are list rows.
	KeyPick = "pk"
	// KeyResult draws a result: the headline in SlotInfo, the stars in the
	// cells from ResultStar0, the lines' labels and values in pairs of cells
	// from ResultLine0 and the rewards from ResultReward0; list rows under
	// them.
	KeyResult = "rs"
	// KeyRadial and the number of items (1 to RadialItems) draw a ring of
	// choices over the whole screen: item i is row i with its value in cell
	// i, the button in the middle is row RadialItems; the title, the line
	// over the ring and the info under it are SlotTitle, SlotBody and
	// SlotInfo.
	KeyRadial = "rd"
	// KeyQuest and a QuestGrids index draw a quest book in a wide window:
	// the chapters as rows down the left (row i its icon and name, the
	// count in row QuestChapters+i), the chapter's heading in SlotInfo and
	// its quests and lines on a dark canvas of cells, QuestGrids[n] wide.
	KeyQuest     = "qk"
	KeyRows      = "Q"
	// KeyLobby after a key draws the lobby's logo and name over the screen.
	KeyLobby = "Y"
	// KeyOverlay after the home key draws the overlay panel.
	KeyOverlay = "V"
)

// ListLayouts are the layouts drawn on the list page.
var ListLayouts = []string{KeyMenu, KeyCards, KeyGrid, KeyBoard, KeyPick, KeyResult}

// WindowLayouts are the layouts drawn in the window with tabs and a bar.
var WindowLayouts = append([]string{KeySplit, KeyListSplit, KeyRange}, ListLayouts...)

// LayoutOf returns the layout of a screen's key: its first two letters.
func LayoutOf(key string) string {
	if len(key) < 2 {
		return key
	}
	return key[:2]
}

// Title is the title of a window opened for the screens of layout. The pack
// builds only the controls of that layout, so a screen of another layout
// opens a new window.
func Title(layout string) string { return Marker + TitleMark(layout) }

// TitleMark is the part of a window title that names its layout.
func TitleMark(layout string) string { return "|" + layout + "|" }

// Family markers say which group of kinds a slot belongs to: the pack draws
// one shape per family and tells its kinds apart with small parts only.
const (
	FamRow  = "§z§g"
	FamSlot = "§z§l"
	FamMini = "§z§k"
)

// The columns of the cell grids of the layouts.
const (
	GridColumns  = 17
	BoardColumns = 11
	SplitColumns = 8
	SplitCells   = 48
	RightColumns = 7
	CardColumns  = 4
	ListRows     = 32
	// PickColumns and PickCards are the cards of a pick screen (KeyPick) a
	// row and in all.
	PickColumns = 3
	PickCards   = 6

	ResultStar0   = 0
	ResultStars   = 3
	ResultLine0   = ResultStar0 + ResultStars
	ResultLines   = 6
	ResultReward0 = ResultLine0 + 2*ResultLines
	ResultRewards = 9

	RadialItems = 8

	// QuestChapters is the most chapters a quest book lists.
	QuestChapters = Rows / 2
)

// QuestGrids are the canvases of a quest book, columns by rows, each within
// Cells.
var QuestGrids = [...][2]int{{11, 10}, {7, 15}}

// Kind markers end a slot's name and say what the slot draws. They are
// invisible format codes the pack takes off the text.
const (
	KindRow       = "§z§a"
	KindStatic    = "§z§s"
	KindChosen    = "§z§c"
	KindHeading   = "§z§h"
	KindDivider   = "§z§d"
	KindToggleOff = "§z§v"
	KindToggleOn  = "§z§x"
	KindTab       = "§z§t"
	KindTabOn     = "§z§u"
	KindBar       = "§z§b"
	KindHelp      = "§z§q"
	KindIcon      = "§z§i"
	KindFrame     = "§z§f"
	KindArrow     = "§z§w"
	KindText      = "§z§y"
	KindMini      = "§z§m"
	KindMiniView  = "§z§n"
	KindBlank     = "§z§e"
	KindRare      = "§z§j"
	KindEpic      = "§z§p"
	// A cell of a quest map: the dark canvas, the half lines from its middle
	// to its top, bottom, left and right edge, and the state of a quest or a
	// line through it (open without one).
	KindCanvas = "§z§8"
	KindLineN  = "§z§1"
	KindLineS  = "§z§2"
	KindLineW  = "§z§3"
	KindLineE  = "§z§4"
	KindDone   = "§z§5"
	KindLocked = "§z§6"
	// A quest canvas cell also draws the lane in the gap right of its quest:
	// the piece from the quest's edge to the lane, from the lane to the next
	// cell, and the lane from the middle height up and down. A quest's shape
	// other than a square, and a NEW tag on a quest or a chapter.
	KindGapW    = "§z§7§1"
	KindGapE    = "§z§7§2"
	KindGapN    = "§z§7§3"
	KindGapS    = "§z§7§4"
	KindDiamond = "§z§7§5"
	KindCircle  = "§z§7§6"
	KindGate    = "§z§7§8"
	KindSquare  = "§z§7§9"
	KindNew     = "§z§9"
	// KindField is the row RowField drawn as a text field over the page's
	// content: a search box.
	KindField = "§z§0"
)

// RowField is the row a KindField draws.
const RowField = Rows - 1

// CountChars is how many characters CountMark writes, and CountKept how
// many of them can be the count's: the pack draws the rest as blanks.
const (
	CountChars = 7
	CountKept  = 5
)

// CountMark is the count text of an item cell as the start of its name: the
// last CountKept characters of count, padded with spaces in front to
// CountChars, each after a format sign so the tooltip hides them. The pack
// cuts that fixed number of bytes off the front, as a count over 64 does not
// fit the stack. A count of 1 or none is blank.
func CountMark(count string) string {
	if count == "1" {
		count = ""
	}
	r := []rune(count)
	if len(r) > CountKept {
		r = r[len(r)-CountKept:]
	}
	var b strings.Builder
	for range CountChars - len(r) {
		b.WriteString("§ ")
	}
	for _, c := range r {
		b.WriteString("§" + string(c))
	}
	return b.String()
}

// Kinds are the kind markers in the order the pack strips them.
var Kinds = []string{KindGapW, KindGapE, KindGapN, KindGapS, KindDiamond, KindCircle, KindGate, KindSquare, KindNew, KindRow, KindStatic, KindChosen, KindHeading, KindDivider, KindToggleOff, KindToggleOn, KindTab, KindTabOn, KindBar, KindHelp, KindIcon, KindFrame, KindArrow, KindText, KindMini, KindMiniView, KindBlank, KindRare, KindEpic, KindCanvas, KindLineN, KindLineS, KindLineW, KindLineE, KindDone, KindLocked, KindField, FamRow, FamSlot, FamMini}
